/* ── WHAT YOU ALREADY PAID FOR ────────────────────────────────────────────────
   Packs and monthly passes you hold. A class page used to offer exactly one way in — pay for this
   session — even when you were carrying ten prepaid sessions at that very studio. A pack is tied
   to the studio that sold it; an unlimited pass has no count, just a date it runs out. */
const PASS_STORE=[
  {id:"mp1",name:"10-Class Pack",studio:"EEE Dance Studio",left:6,of:10,expires:"31 Oct 2026"},
  {id:"mp2",name:"Unlimited Monthly",studio:"Bounce Dance Academy",left:null,of:null,expires:"22 Aug 2026"}];
/* the pass that covers a given studio, if you hold one with anything left on it */
const dosPassFor=(studioName)=>{const n=String(studioName||"").trim().toLowerCase();
  if(!n)return null;
  return PASS_STORE.find(p=>String(p.studio||"").trim().toLowerCase()===n&&(p.left==null||p.left>0))||null;};
const dosUsePass=(id)=>{const p=PASS_STORE.find(x=>x.id===id);
  if(!p)return false;
  if(p.left!=null){if(p.left<=0)return false;p.left-=1;}
  return true;};

