const PulseGrid=({rows,D,fmt,setPulse})=>(<div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:7}}>
  {rows.map(([l,t,lm,u,g,nav,det])=>{const dl=D(t,lm,g);
    return(<div role="button" tabIndex={0} onKeyDown={dosKey} key={l} onClick={()=>setPulse({l,t,lm,u,g,nav,det,fmt})}
      style={{background:"var(--card)",border:"1px solid var(--el)",borderRadius:12,padding:"9px 10px",cursor:"pointer"}}>
      <div style={{display:"flex",alignItems:"baseline",gap:6}}>
        <span style={{fontSize:14,fontWeight:900,letterSpacing:-.2}}>{fmt(t,u)}</span>
        <span style={{fontSize:8.5,fontWeight:900,color:dl.ok?"#22C55E":"#F87171"}}>{dl.up?"▲":"▼"}{dl.d}%</span></div>
      <div style={{fontSize:8.5,fontWeight:800,letterSpacing:.3,textTransform:"uppercase",color:"var(--sub)",marginTop:2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{l}</div>
    </div>);})}
</div>);

