/* published events, shared by every events surface */
const eventsForList=()=>{
  try{
    const extra=(typeof EVENT_STORE!=="undefined"?EVENT_STORE:[]).filter(e=>e.status==="Published").map(e=>({
      id:e.id,c:e.cat==="battle"?"battle":e.cat==="tournament"?"tournament":"showcase",
      t:e.title,col:e.col||"#F59E0B",km:"—",when:e.when,time:e.time,city:e.city,venue:e.venue,
      price:(e.ticketsOn===false||!(e.tiers||[]).length)?"Free":"₹"+((e.tiers||[[0,0]])[0][1]||0),store:true}));
    return extra;
  }catch(e){return [];}
};

const eventsForTab=()=>{
  try{
    const extra=(typeof EVENT_STORE!=="undefined"?EVENT_STORE:[]).filter(e=>e.status==="Published").map(e=>({
      id:e.id,kind:e.cat==="battle"?"battle":e.cat==="tournament"?"tournament":"showcase",
      t:e.title,when:e.when,time:e.time,city:e.city,venue:e.venue,
      price:(e.ticketsOn===false||!(e.tiers||[]).length)?"Free":"₹"+((e.tiers||[[0,0]])[0][1]||0),
      /* the listing has to carry what decides who may enter and how many there is room for, or
         the card falls back to a default and prints no format and no denominator */
      /* ticketsOn travels too: an audition's tiers are its SLOTS, and a listing that loses the
         flag reports forty slots a second time as forty spectator seats */
      ticketsOn:e.ticketsOn!==false,
      styles:e.styles||[],format:e.format||null,entry:e.entry||null,entryTiers:e.entryTiers||null,
      participants:e.participants||[],tiers:e.tiers||[],rounds:e.rounds,bracket:e.bracket,
      /* `audCap` is read for events SAVED before the audition category was removed — their
         slot count still means something as a capacity. Nothing writes it any more. */
      slots:e.audCap||e.slots||0,grad:[e.col||"#F59E0B","#7C3AED"],store:true}));
    return extra;
  }catch(e){return [];}
};

