/* ═══════════════════════════════════════════════════════════════════════
   DOSDB — single owner for everything that is NOT a person.
   People stay in their own role-specific stores (STUDENTS,
   CREWS[n].members, POOL_*) because roles differ per context.
   Screens should read through these accessors, never their own copies.
   ═══════════════════════════════════════════════════════════════════════ */
const DOSDB={
  classes:CLASS_STORE,      /* studio's class catalogue */
  events:EVENT_STORE,       /* every event, any status */
  choreos:CHOREO_STORE,     /* routines, with usage */
  bookings:BOOK_STORE,      /* confirmed class + event bookings */
  passes:PASS_STORE,        /* packs and monthly passes you already paid for */
  requests:REQ_STORE,       /* battles + studio rentals */
  enquiries:ENQ_STORE,      /* leads */
  rentals:RENTALS,          /* hourly room rates */
  payMethods:PAY_STORE,     /* cards · UPI · cash */
  published:PUBLISHED,      /* shareable booking links */

  /* ── reads ── */
  sessions(){try{return (typeof window!=="undefined"&&window.__DOSUPCOMING)?window.__DOSUPCOMING():[];}catch(e){return [];}},
  classesFor(status){return DOSDB.classes.filter(c=>!status||c.status===status);},
  liveClasses(){return DOSDB.allClasses().filter(dosClassLive);},
  /* the desk is a studio's OWN desk: filter by owner as well as status. `all===true` is for the
     surfaces that genuinely want every event — Discover and the public lists. */
  eventsFor(status,all){return DOSDB.events.filter(e=>
    (!status||e.status===status)&&(all===true||dosOwnsEvent(e)));},
  eventById(id){return DOSDB.events.find(e=>e.id===id)||null;},
  openRequests(){return DOSDB.requests.filter(r=>r.status==="pending");},
  openEnquiries(){return DOSDB.enquiries.filter(e=>["New","Quoted","Trial booked"].includes(e.status));},
  /* Classes you RUN = your catalogue + the sessions on the calendar that you teach, de-duplicated.
     Sessions you merely attend belong to Home, not to the business manager — counting them here
     is what made someone else's class show up as "live" in your own register. */
  allClasses(){
    const me=(typeof window!=="undefined"&&window.__DOSACCOUNT&&window.__DOSACCOUNT().name)||"";
    /* de-duplicated by the SESSION, not by its name: names were unique once and are gone now, and
       keying on the style alone would fold three Hip-Hop batches into one row */
    const kOf=(style,win)=>`${String(style||"").trim().toLowerCase()}|${String(win||"").trim()}`;
    const seen={};DOSDB.classes.forEach(c=>{seen[kOf(c.style||c.t,dosSchedWindow(c.sched))]=1;});
    const extra=[];
    DOSDB.sessions().filter(u=>u.kind!=="event").forEach(u=>{
      if(me&&u.teacher&&u.teacher!==me)return;               /* not yours to manage */
      const key=kOf(u.style||u.name,u.time);if(seen[key])return;seen[key]=1;
      const cap=+(String(u.capacity).split("/")[1])||16,fil=+(String(u.capacity).split("/")[0])||0;
      const lvl=(u.e&&u.e.level)||u.level||"";
      const stu=(u.e&&u.e.studio&&u.e.studio.name)||u.studio||"";
      extra.push({id:"live"+extra.length,t:dosClassLabel({kind:"class",style:u.style||u.name,level:lvl}),
        style:u.style,level:lvl,studio:stu,col:u.col,
        /* keep the WHOLE window, not just the start — this is what decides liveness */
        sched:`${u.when} · ${u.time||""}`,trainer:u.teacher||"—",
        room:`${u.room}${u.location?" · "+u.location:""}`,price:+u.price||300,
        cap,filled:fil,status:"Published"});});
    return [...DOSDB.classes,...extra];
  },

  /* ── ONE LIST OF WAYS TO PAY ──────────────────────────────────────────────────────────────
     There were three. A class offered UPI / Card / Netbanking as CATEGORIES — not anything you
     own, just three words — plus your pack. An event offered the instruments actually on your
     account, minus the pack. And Payments settings kept its rows in component state, so a method
     you added there existed until you left the page and was never once offered at checkout.
     Three places disagreeing about what you can pay with, and only one of them was real.

     PAY_STORE is that one now. `methods()` is what every sheet renders and what settings edits;
     the pack is NOT in it, because a pack is not a way to pay for things in general — it is a
     thing you already bought, and the class sheet shows it above the list where it applies. */
  methods(){return PAY_STORE;},
  payMethod(){return PAY_STORE.find(m=>m.def)||PAY_STORE[0]||null;},
  addMethod(m){
    if(!m||!m.label)return null;
    const row={id:m.id||("p"+PAY_STORE.length+"-"+String(m.label).replace(/\W+/g,"").slice(0,6)),
      kind:m.kind||"Card",label:String(m.label),sub:m.sub||"Verified",def:!!m.def||PAY_STORE.length===0};
    if(row.def)PAY_STORE.forEach(x=>{x.def=false;});
    PAY_STORE.push(row);dosTouch();return row;
  },
  removeMethod(id){
    const i=PAY_STORE.findIndex(m=>String(m.id)===String(id));
    if(i<0)return false;
    const wasDef=PAY_STORE[i].def;
    PAY_STORE.splice(i,1);
    /* the default cannot be a method that no longer exists — something has to be the one that
       is offered first, or the next sheet opens with nothing chosen */
    if(wasDef&&PAY_STORE.length)PAY_STORE[0].def=true;
    dosTouch();return true;
  },
  defaultMethod(id){
    let hit=false;PAY_STORE.forEach(m=>{const on=String(m.id)===String(id);if(on)hit=true;m.def=on;});
    if(hit)dosTouch();return hit;
  },

  /* ── writes · the only places that mutate ── */
  publishClass(rec){DOSDB.classes.unshift({id:"c"+Date.now(),status:"Published",filled:0,cap:16,...rec});},
  addEvent(ev){DOSDB.events.unshift({id:"e"+Date.now(),owner:dosOwnerId(),status:ev.draft?"Draft":"Published",
    participants:[],audience:[],tiers:ev.tiers||[],judges:ev.judges||[],slots:ev.slots||[],results:[],...ev});},
  /* ── ONE BOOKING, ONE SEAT ────────────────────────────────────────────────────────────────
     This took two. The class page called `__DOSBOOKED` — which lands here and fills the seat —
     and then ALSO bumped the calendar itself and wrote `CLASS_STORE[i].filled += 1` by hand.
     `DOSDB.classes` IS `CLASS_STORE`, so the same seat was taken twice: a class went 9/16 → 11/16
     on one booking, filled at double speed, and showed the wrong spots left on every card in the
     app. The comment above that code read "one booking = one seat, everywhere".

     And the match was fuzzy in a way that could take seats off OTHER classes: it fired on
     `key.includes(style)`, so booking a Contemporary class bumped every Contemporary class on
     the roster. An id is exact; a title is exact; the style test is the last resort it always
     should have been, and it now stops at the first thing it finds. */
  fill(idOrTitle,delta,id){
    const key=String(idOrTitle||"").toLowerCase();
    const list=DOSDB.classes;
    const byId=id?list.find(c=>String(c.id)===String(id)):null;
    const exact=byId||list.find(c=>String(c.t||"").toLowerCase()===key);
    const hit=exact||list.find(c=>{const nm=String(c.t||"").toLowerCase();return nm&&key.includes(nm);})
      ||list.find(c=>{const st=String(c.style||"").toLowerCase();return st&&key.includes(st);});
    if(hit)hit.filled=Math.max(0,Math.min(hit.cap,(hit.filled||0)+delta));
    try{if(window.__DOSBUMPCAP)window.__DOSBUMPCAP(idOrTitle,delta);}catch(e){dosWarn(e);}
    return !!hit;
  },
  book(b){
    if(b&&b.kind==="class")DOSDB.fill(b.title,1,b.id);
    DOSDB.bookings.unshift({id:"bk"+Date.now(),
      code:"DOS-"+(b.kind==="event"?"EV":"CL")+"-"+String(Math.floor(1000+Math.random()*8999)),
      col:b.col||"#3B82F6",...b});
    return true;
  },
  /* ── CANCELLING GIVES THE SEAT BACK ───────────────────────────────────────────────────────
     Nothing in the app released a seat. You could ask for your money back, but the seat stayed
     taken: a full class stayed full for ever and the people on its waitlist could never move up,
     blocked by somebody who had already gone.

     The seat comes back IMMEDIATELY, and the refund goes off on its own track. Those are two
     different questions with two different answers and two different clocks — whether you are
     coming (now, and you know it) and how much money comes back (the host's policy, the host's
     timing). Holding the seat until a refund is approved would let a host who takes three days
     keep a seat dead for three days, which helps nobody and least of all the person waiting.

     The refund WINDOW still decides the amount: outside it you are due the money, inside it the
     host decides. That is what `dosRefundDue` says, and the sheet says it too. */
  cancel(bk){
    if(!bk)return false;
    const kind=bk.kind==="event"?"event":"class";
    /* 1 · the seat goes back to the pool it came from */
    if(kind==="class"){DOSDB.fill(bk.title,-(+bk.qty||1),bk.id);}
    else{const ev=DOSDB.events.find(e=>e.id===bk.id)
        ||DOSDB.events.find(e=>String(e.title||"").toLowerCase()===String(bk.title||"").toLowerCase());
      if(ev){
        if(String(bk.as||"")==="participant"){
          const me=String((dosAccount()||{}).name||"").toLowerCase();
          ev.participants=(ev.participants||[]).filter(x=>String(x.n||"").toLowerCase()!==me
            &&!String(x.n||"").toLowerCase().startsWith(me+" &"));
        }else{
          const n=Math.max(1,+bk.qty||1);
          const t=(ev.tiers||[]).find(x=>String(x[0]).toLowerCase()===String(bk.tier||"").replace(/\s*×\d+$/,"").toLowerCase())||(ev.tiers||[])[0];
          if(t)t[3]=Math.max(0,(+t[3]||0)-n);
          const me=String((dosAccount()||{}).name||"").toLowerCase();
          let drop=n;
          ev.audience=(ev.audience||[]).filter(a=>{
            if(drop>0&&String((a||[])[0]||"").toLowerCase()===me){drop--;return false;}return true;});
        }}}
    /* 2 · the booking stops being one */
    const i=DOSDB.bookings.findIndex(x=>x.id===bk.id||(x.code&&x.code===bk.code)
      ||(String(x.title||"")===String(bk.title||"")&&x.kind===bk.kind));
    if(i>-1)DOSDB.bookings.splice(i,1);
    /* 3 · and whoever was waiting is told there is room */
    const first=(waitList(bk.title)||[])[0]||null;
    if(first){waitLeave(bk.title,first.n);
      try{if(window.__DOSWAITCALL)window.__DOSWAITCALL(bk.title,first.n);}catch(e){dosWarn(e);}}
    dosTouch();
    return {freed:true,offered:first?first.n:null};
  },
  request(o){DOSDB.requests.unshift({id:"rq"+Date.now(),status:"pending",time:"now",...o});return true;},
  respond(id,status){const r=DOSDB.requests.find(x=>x.id===id);if(r)r.status=status;return !!r;},
  setEnquiry(id,status){const e=DOSDB.enquiries.find(x=>x.id===id);if(e)e.status=status;return !!e;}
};

/* ── WHOSE FLOOR IS THIS? ──────────────────────────────────────────────────────────────────
   The register drew every row without a studio. Adding the field to the seed records did not
   fix it, and could not: the class store is persisted, so a record written before the field
   existed comes back from storage without it forever, and the seed is only ever read once, on a
   machine that has never run the app. Anything that depends on a record having been written
   correctly is a fix that works for exactly one person.

   So it is derived instead, from the two things every class record does carry — the room and the
   city. The calendar already knows which studio holds which room, because its sessions name both;
   that is read first, so the answer follows the data rather than a list someone has to maintain.
   The table underneath is the fallback for rooms today's calendar happens not to mention. */
const DOS_ROOM_STUDIO={
  "studio a|pune":"EEE Dance Studio","studio b|pune":"EEE Dance Studio",
  "auditorium|pune":"EEE Dance Studio","kala hall|pune":"Adishakti Gurukul",
  "hall 2|noida":"Adishakti Gurukul","main hall|mumbai":"Fusion Dance Center",
  "studio b|mumbai":"Fusion Dance Center","main hall|new delhi":"EEE Dance Studio",
  "hall 1|new delhi":"Bounce Dance Academy","hall 2|new delhi":"Bounce Dance Academy",
  "studio a|new delhi":"Bounce Dance Academy","studio b|new delhi":"Fusion Dance Center"};
const dosPlaceKey=(room,city)=>`${String(room||"").split(/[,·]/)[0].trim().toLowerCase()}|${String(city||"").trim().toLowerCase()}`;
const dosStudioOf=(room,city,fallback)=>{
  const rm=String(room||"").split(/[,·]/)[0].trim();
  if(!rm)return fallback||"";
  const ct=dosCity(String(city||"").trim())||dosCityIn(String(room||""))||String(city||"").trim();
  try{
    const hit=DOSDB.sessions().find(u=>{
      const nm=(u.e&&u.e.studio&&u.e.studio.name)||u.studio||"";
      if(!nm)return false;
      const uc=dosCityIn(u.location||"")||dosCity(u.location||"");
      return dosPlaceKey(u.room,uc)===dosPlaceKey(rm,ct);});
    if(hit)return (hit.e&&hit.e.studio&&hit.e.studio.name)||hit.studio;
  }catch(e){dosWarn(e);}
  return DOS_ROOM_STUDIO[dosPlaceKey(rm,ct)]||fallback||"";};

/* ═══════════ PEOPLE · students · faculty · assistants · crew ═══════════ */
const ROLE_META={
  student:{label:"Student",c:"#3B82F6",metric:"attendance",unit:"%"},
  faculty:{label:"Faculty",c:"#8B5CF6",metric:"sessions taught",unit:""},
  assistant:{label:"Assistant",c:"#F59E0B",metric:"sessions assisted",unit:""},
  crew:{label:"Crew",c:"#DC2626",metric:"practice",unit:"%"}};

/* ── WHOSE STUDENTS ───────────────────────────────────────────────────────────
   A studio's roster and an artist's roster are not the same people. The studio teaches batches
   in its halls; the artist teaches their own — privates, small groups, the ones who followed
   them from a workshop. Kept as one list they were the same four names on both pages, which is
   not a smaller version of the truth, it is the wrong one. The studio's roster is PEOPLE below;
   the artist's is here, and the Students page reads whichever belongs to the workspace you are
   standing in. */
/* ── A ROSTER ROW MUST NOT BE ABLE TO TAKE THE PAGE DOWN ────────────────────────────────────
   The Students page was reported broken four times, and four sweeps found nothing — because
   every sweep booted the app with the SEED roster, where every record is complete. The page
   reads about twenty fields off each person and trusted all of them. One record short of one
   field, and:

       p.styles.join(" · ")     →  Cannot read properties of undefined (reading 'join')

   which the error boundary turns into "This screen hit a snag". The list dies, the record
   behind it dies, and — because the bad record is in the store rather than in the render — it
   dies again on every visit, forever. That is exactly what "still not fixed" looks like from
   the outside: a page that is broken permanently, on one machine, that a clean boot always
   shows working.

   A short record is not an exceptional condition. It is what a person ADDED through the app
   looks like (quick sign-up writes a name and a mobile and nothing else), and it is what a
   store restored from an older build looks like — `dosApply` replaces a saved array WHOLE, so
   every field added to a record since that save is simply absent for a returning user.

   So the roster is read through here, and nowhere else. Every field the two pages touch has a
   defined shape on the way out. A person the app knows nothing about renders as a person the
   app knows nothing about — a name, and honest blanks — instead of a crash. */
const DOS_PERSON_DEFAULTS={att:0,sessions:0,spend:0,punctual:0,gap:0,noShow:0,cancels:0};
const dosPerson=(p)=>{
  const r=(p&&typeof p==="object")?p:{n:String(p||"Unknown")};
  const num=(v)=>(typeof v==="number"&&isFinite(v))?v:0;
  const list=(v)=>Array.isArray(v)?v:[];
  /* a series is drawn as a line, and a line needs two points — one reading is repeated rather
     than left to divide by zero (58/(1-1) is Infinity, and an Infinity in a path `d` is a
     silently invisible chart) */
  const series=(v)=>{const a=list(v).filter(x=>typeof x==="number"&&isFinite(x));
    return a.length>1?a:a.length===1?[a[0],a[0]]:[0,0];};
  const out={...r};
  out.n=String(r.n||r.name||"Unknown");
  out.id=r.id!=null?r.id:`p-${dosHash(out.n)}`;
  /* an unrecognised label is still a person — ROLE_META[p.role].c threw on the way past */
  out.role=(r.role&&ROLE_META&&ROLE_META[r.role])?r.role:"student";
  out.styles=list(r.styles).map(x=>String(x)).filter(Boolean);
  out.g=(Array.isArray(r.g)&&r.g.length>1)?r.g:["#5AC8FA","#7C3AED"];
  out.since=r.since?String(r.since):"—";
  out.city=r.city?String(r.city):"—";
  out.last=r.last?String(r.last):"—";
  out.risk=r.risk?String(r.risk):"—";
  Object.keys(DOS_PERSON_DEFAULTS).forEach(k=>{out[k]=num(r[k]);});
  out.trend=series(r.trend);
  out.long=series(r.long!=null?r.long:r.trend);
  out.money=series(r.money);
  out.packs=list(r.packs).filter(x=>x&&typeof x==="object");
  out.classes=list(r.classes);
  return out;};
/* the only way the app reads a list of PEOPLE (there is already a `dosRoster` for teams) */
const dosPeople=(l)=>(Array.isArray(l)?l:[]).map(dosPerson);
/* published so the contract can be asserted from outside — see smoke-students */
if(typeof window!=="undefined")window.__DOSPERSON=dosPerson;

