const G=["#EC4899","#3498DB"];
const CREWS_DATA=[["EEE Crew","EC",["#7C3AED","#EC4899"],"leader"],["Raftaar Rebels","RR",["#922B21","#00CEC9"],"member"]];
/* followers/following — each row segregated by account type, incl. teams/crews */
